import"./chunk-2NFLSA4Y.js";var i={quantumDoubleSlit:{theory:{concept:"The double-slit experiment with photons sent one at a time demonstrates light's [[wave\u2013particle duality]]. Each photon is detected at a single spot on the screen, showing particle-like behaviour. Even when photons are sent individually at separate times, many detections build an interference pattern: alternating bright and dark bands reveal light's wave-like behaviour. This pattern occurs when both slits are open and no measurement determines which slit the photon passes through."},section:{setup:{title:"What is being measured?",text:"A coherent monochromatic source illuminates two identical narrow slits. We record where photons arrive on the screen. [[A recorded dot does not reveal which slit the photon passed through.]] This simulation does not calculate or draw a path between source and screen."},probability:{title:"Random spots, predictable pattern",text:"[[The interference pattern predicts probabilities, not the next individual spot.]] Bright regions of the corresponding optical pattern are more likely to record a photon. Reset starts another numbered experiment; the fluctuations change while the underlying distribution stays the same."},spacing:{title:"Move the bands",text:"[[Longer wavelengths spread the bands apart; wider slit separation brings them closer.]] Near the centre their spacing is approximately \u03BBL/d. A farther screen also spreads them apart. Changing the apparatus clears earlier detections so different patterns are never mixed."},compare:{title:"Compare prediction with measurements",text:"[[With more detections, measured frequencies tend to approach the predicted probabilities.]] The solid bars show measured relative frequencies; the optional dashed curve shows predicted bin probabilities on the same scale. The graph compares the fraction within the central interval \u2212\u0394x/2 to +\u0394x/2. Small random differences remain in any finite sample."}},param:{wavelength:"Photon wavelength",separation:"Slit separation",rate:"Detections per teaching second",distance:"Screen distance",width:"Width of each slit",seed:"Experiment number",timeStep:"Simulation timestep"},hint:{wavelength:"Wavelength of the monochromatic light. Changing it starts a fresh pattern.",separation:"Distance between the centres of the two slits. Both remain open.",rate:"Rate of detections in the displayed screen window. This changes teaching time, not photon flight speed or the probability pattern.",distance:"Physical distance from the slits to the screen.",width:"A wider slit narrows the broad diffraction envelope.",seed:"Reset selects the next experiment. The same number and settings reproduce the same detection sequence."},preset:{blue:"Blue \xB7 450 nm",red:"Red \xB7 650 nm",close:"Close slits \xB7 0.25 mm",far:"Farther apart \xB7 0.50 mm",slow:"Watch single spots",fast:"Build the pattern quickly"},measure:{detections:"Detected photons",spacing:"Central band spacing (approx.)",time:"Teaching time",observed:"Central interval: measured",expected:"Central interval: predicted"},visual:{detections:"Detected spots",histogram:"Measured distribution",expected:"Predicted distribution (dashed)"},view:{screen:"Detector screen \xB7 front view",count:"{n} / {total} photons detected",histogram:"Distribution across the screen",legend:"Bars: measured relative frequency",legendExpected:"Bars: measured \xB7 dashed: predicted",schematic:"Vertical spread is schematic; no photon paths are shown"},graph:{central:"Fraction in the central interval versus teaching time"},formula:{spacing:"Approximate spacing near the centre (small angles)",probability:"Conditional probability in one equal screen bin",intensity:"Fraunhofer intensity; sin\u03B8 = x/\u221A(L\xB2+x\xB2), sinc(u) = sin(u)/u, sinc(0) = 1"},variable:{probability:"Probability of detection in bin i, given detection on this screen"},assumption:{optics:"Fraunhofer far-field approximation: coherent monochromatic photons, identical uniformly lit slits, no polarization or photon interactions. Both slits stay open; no which-path detector is modelled.",screen:"Only detections within the displayed \u22129 to +9 mm interval are counted. Probabilities are normalized within that interval; this is not a model of the total source flux or photons missing the screen.",sampling:"The screen has 181 equal bins. Bin probabilities use the intensity at each midpoint; positions inside a bin are uniform. Independent seeded samples reproduce a run rather than provide true quantum randomness.",time:"Detections are scheduled evenly in accelerated teaching seconds. Real arrival-time statistics and photon propagation times are not modelled. A run ends after 2400 detections.",drawing:"The screen is shown face-on. Only its horizontal coordinate represents the calculated interference distribution; vertical dot spread is illustrative. The drawing does not show a scaled apparatus or photon trajectories."},challenge:{collect:{title:"Build a pattern",description:"Complete a run with at least 2000 detections and inspect the bands.",hint:"Let the run finish. Increase the detection rate to collect the pattern faster."},wide:{title:"Spread the bands",description:"Collect at least 2000 detections with central band spacing of at least 3 mm.",hint:"Use a longer wavelength and bring the slits closer together."},narrow:{title:"Bring the bands closer",description:"Collect at least 2000 detections with spacing no greater than 1.1 mm.",hint:"Use blue light and move the slits farther apart."},agreement:{title:"Compare probabilities",description:"Collect at least 2000 detections with the measured central fraction within 5 percentage points of its prediction.",hint:"Enable the predicted distribution and let a full run accumulate. Small fluctuations are expected."}}}},n={sim:i};export{n as default,i as sim};
